@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  /* Light Theme (Default) */
  --app-bg: #fafaf9; /* stone-50 */
  --surface: #ffffff;
  --surface-sec: #f5f5f4; /* stone-100 */
  --text-primary: #292524; /* stone-800 */
  --text-secondary: #a8a29e; /* stone-400 */
  --border: #a8a29e; /* stone-400 */
  --icon: #57534e; /* stone-600 */
  --board-bg: #ffffff;
  --overlay-opacity: 0;

  /* Grid Lines */
  --grid-thin: #a8a29e; /* stone-400 */
  --grid-thick: #1c1917; /* stone-900 */
}

.dark {
  /* Dark Theme - OLED Black (Pure Black) */
  --app-bg: #000000; 
  --surface: #121212; /* Very dark grey for cards (Material Dark) */
  --surface-sec: #262626; /* Slightly lighter for inputs */
  --text-primary: #f5f5f4; /* Stone 100 */
  --text-secondary: #a3a3a3; /* Neutral 400 */
  --border: #404040; /* Neutral 700 */
  --icon: #d4d4d4; /* Neutral 300 */
  --board-bg: #292524; /* Stone 800 - Dark Grid Background */
  --overlay-opacity: 0.5;

  /* Grid Lines - Dark Mode (Lighter for contrast against dark bg) */
  --grid-thin: #57534e; /* Stone 600 */
  --grid-thick: #a8a29e; /* Stone 400 */
}

/* STRICT VIEWPORT LOCKING FOR MOBILE */
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  position: fixed; /* Prevents elastic scrolling on iOS */
  overflow: hidden;
  background-color: var(--app-bg);
  font-family: 'Outfit', sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  -webkit-tap-highlight-color: transparent;
  transition: background-color 0.3s;

  /* Disable selection and zooming */
  user-select: none;
  -webkit-user-select: none;
  touch-action: manipulation;
  overscroll-behavior: none;
}

#root {
  width: 100%;
  height: 100%;
  position: absolute;
  top: 0;
  left: 0;
  overflow: hidden;
}

/* Hide all scrollbars but allow scrolling functionality where needed */
::-webkit-scrollbar {
  width: 0px;
  background: transparent;
}
* {
  scrollbar-width: none;
  -ms-overflow-style: none;
  /* Prevent default touch actions like double-tap zoom globally */
  touch-action: manipulation;
}

/* Safe Area Utilities */
.pt-safe {
  padding-top: env(safe-area-inset-top);
}
.pb-safe {
  padding-bottom: env(safe-area-inset-bottom);
}
.h-safe-screen {
  height: 100vh; /* Fallback */
  height: 100dvh;
}

/* Landscape Blocker Logic */
/* Only show on screens that are likely mobile phones in landscape */
@media screen and (orientation: landscape) and (max-height: 600px) {
  .landscape-blocker {
    display: flex !important;
  }
}

/* TEXT EFFECTS */

/* 1. ELEGANT GOLD - REIMAGINED */
.text-shine-gold {
  background-image: linear-gradient(
    110deg,
    #854d0e 15%,   /* Yellow 800 */
    #ca8a04 35%,   /* Yellow 600 */
    #fde047 50%,   /* Yellow 300 */
    #ca8a04 65%,   /* Yellow 600 */
    #854d0e 85%    /* Yellow 800 */
  );
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: flow-light 4s linear infinite; 
  font-weight: 700;
  filter: drop-shadow(0px 1px 1px rgba(113, 63, 18, 0.25));
}

/* 2. REIMAGINED DIAMOND - PRISMATIC CRYSTAL */
.text-shine-diamond {
  background-image: linear-gradient(
    110deg,
    #0369a1 15%,   /* Sky 700 */
    #0ea5e9 35%,   /* Sky 500 */
    #e0f2fe 50%,   /* Sky 100 */
    #0ea5e9 65%,   /* Sky 500 */
    #0369a1 85%    /* Sky 700 */
  );
