}

/* 3. REIMAGINED RUBY - PREMIUM RED */
.text-shine-ruby {
  background-image: linear-gradient(
    110deg,
    #be123c 15%,   /* Rose 700 */
    #f43f5e 35%,   /* Rose 500 */
    #ffe4e6 50%,   /* Rose 100 */
    #f43f5e 65%,   /* Rose 500 */
