}

/* 8. PREMIUM DEEP BLUE BUTTON (New) */
.btn-premium-deep {
  position: relative;
  background-color: #0b0f19; 
  overflow: hidden;
  z-index: 1;
  background: linear-gradient(
    110deg, 
    #0b0f19 0%,
    #0b0f19 60%,    
    #1e3a8a 70%,    
    #60a5fa 75%,    
    #1e3a8a 80%,    
    #0b0f19 90%,    
    #0b0f19 100%
  );
  background-size: 200% 100%;
  animation: deep-sweep 3s linear infinite; 
