    hasPendingPepinoGift?: boolean;
}

const SUBTITLES = [
    "Choose your pace",
    "Find your flow",
    "Time to focus",
    "Relax and solve",
    "Pick your challenge",
    "Sharpen your mind",
    "Enjoy the quiet",
    "A moment of zen",
