                            const isLocked = (tabNum === 2 && !isPack2Unlocked) || (tabNum === 3 && !isPack3Unlocked);

                            return (
                                <button
                                    key={tabNum}
                                    onClick={() => handleTabChange(tabNum as 1|2|3)}
                                    className={`
